/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_emotions))
        .routes(routes!(list_genders, create_gender))
        .routes(routes!(update_gender, delete_gender))
        .routes(routes!(list_pronouns, create_pronoun))
        .routes(routes!(update_pronoun, delete_pronoun))
        .routes(routes!(list_address_types, create_address_type))
        .routes(routes!(update_address_type, delete_address_type))
        .routes(routes!(list_pet_categories, create_pet_category))
        .routes(routes!(update_pet_category, delete_pet_category))
        .routes(routes!(list_contact_information_types, create_contact_information_type))
        .routes(routes!(update_contact_information_type, delete_contact_information_type))
        .routes(routes!(list_call_reason_types, create_call_reason_type))
        .routes(routes!(update_call_reason_type, delete_call_reason_type))
        .routes(routes!(create_call_reason))
        .routes(routes!(update_call_reason, delete_call_reason))
        .routes(routes!(list_gift_occasions, create_gift_occasion))
        .routes(routes!(update_gift_occasion, delete_gift_occasion))
        .routes(routes!(list_gift_states, create_gift_state))
        .routes(routes!(update_gift_state, delete_gift_state))
        .routes(routes!(list_relationship_group_types, create_relationship_group_type))
        .routes(routes!(update_relationship_group_type, delete_relationship_group_type))
        .routes(routes!(create_relationship_type))
        .routes(routes!(update_relationship_type, delete_relationship_type))
        .routes(routes!(list_religions, create_religion))
        .routes(routes!(update_religion, delete_religion))
        .routes(routes!(list_account_currencies))
        .routes(routes!(enable_all_account_currencies))
        .routes(routes!(disable_all_account_currencies))
        .routes(routes!(update_account_currency))
}
